-- Integration tests run in one transaction. No test orders or inventory changes survive.
begin;
do $$
declare p uuid;actor uuid;before_stock integer;items jsonb;quote jsonb;result jsonb;again jsonb;request uuid;token text;order_id uuid;
 fixture uuid:=gen_random_uuid();v0 uuid:=gen_random_uuid();v1 uuid:=gen_random_uuid();failure boolean;
 customer jsonb:='{"name":"Kiểm thử tự động","phone":"0900000000","address":"Địa chỉ kiểm thử không giao hàng","city":"Hà Nội","consent":true}'::jsonb;
begin
 select id,stock into p,before_stock from public.products where slug='milk-tea-brown';
 select user_id into actor from public.admin_users limit 1;
 assert actor is not null,'Existing admin is required for status tests';
 items:=jsonb_build_array(jsonb_build_object('product_id',p,'quantity',1,'left_power',0,'right_power',-1.25,'box_price',1));
 quote:=public.commerce_quote(items);
 assert (quote->>'subtotal')::numeric=(select price from public.products where id=p),'Client price must be ignored';
 assert (quote->'items'->0->>'left_power')::numeric=0 and (quote->'items'->0->>'right_power')::numeric=-1.25,'One box retains distinct powers';
 assert quote->>'shipping_fee' is null and quote->>'total' is null,'Unconfigured shipping is not free';
 request:=gen_random_uuid();token:=repeat('a',64);
 result:=public.commerce_create_order(request,token,customer,items,quote->>'quote_hash',null,gen_random_uuid()::text,gen_random_uuid()::text);
 order_id:=(result->>'id')::uuid;
 assert (select stock from public.products where id=p)=before_stock-1,'One legacy box reserved';
 again:=public.commerce_create_order(request,token,customer,items,quote->>'quote_hash',null,'same','same');
 assert result->>'code'=again->>'code' and (again->>'replayed')::boolean,'Retry reuses order';
 assert (select stock from public.products where id=p)=before_stock-1,'Retry cannot reserve stock twice';
 failure:=false;begin perform public.commerce_create_order(request,repeat('b',64),customer,items,quote->>'quote_hash',null,'same','same');exception when others then failure:=sqlerrm like '%INVALID_RECEIPT%';end;assert failure,'Wrong receipt cannot replay another order';
 failure:=false;begin perform public.commerce_transition_order(order_id,null,'cancelled','{}');exception when others then failure:=sqlerrm like '%ADMIN_REQUIRED%';end;assert failure,'Status writes require verified admin';
 failure:=false;begin perform public.commerce_transition_order(order_id,actor,'shipped','{}');exception when others then failure:=sqlerrm like '%INVALID_TRANSITION%';end;assert failure,'Cannot skip confirmation';
 failure:=false;begin perform public.commerce_transition_order(order_id,actor,'confirmed','{}');exception when others then failure:=sqlerrm like '%CUSTOMER_CONFIRMATION_REQUIRED%';end;assert failure,'Cannot confirm unknown customer total';
 perform public.commerce_transition_order(order_id,actor,'cancelled','{}');
 perform public.commerce_transition_order(order_id,actor,'cancelled','{}');
 assert (select stock from public.products where id=p)=before_stock,'Cancel restores stock exactly once';
 failure:=false;begin perform public.commerce_quote(jsonb_build_array(jsonb_build_object('product_id',p,'quantity',1,'left_power','','right_power',-1)));exception when others then failure:=true;end;assert failure,'Empty power is not plano';
 failure:=false;begin perform public.commerce_quote(jsonb_build_array(jsonb_build_object('product_id',p,'quantity',1,'left_power',-0.5,'right_power',-1)));exception when others then failure:=sqlerrm like '%INVALID_POWER%';end;assert failure,'Unsupported half power rejected';
 update public.products set price=price+1 where id=p;
 failure:=false;begin perform public.commerce_create_order(gen_random_uuid(),repeat('c',64),customer,items,quote->>'quote_hash',null,gen_random_uuid()::text,gen_random_uuid()::text);exception when others then failure:=sqlerrm like '%QUOTE_CHANGED%';end;assert failure,'Price change requires review';
 update public.products set price=price-1 where id=p;
 insert into public.products(id,name,slug,color,diameter,wear_period,price,stock,active,catalog_visible,inventory_mode,image_url) values(fixture,'TEST ONLY','test-'||fixture,'Brown','14.5','6 tháng',220000,0,true,false,'variant','https://example.com/test.webp');
 insert into public.product_variants(id,product_id,sku,power,unit_label,stock) values(v0,fixture,'test-0-'||fixture,0,'1 chiếc',3),(v1,fixture,'test-1-'||fixture,-1,'1 chiếc',2);
 items:=jsonb_build_array(jsonb_build_object('product_id',fixture,'quantity',1,'left_variant_id',v0,'right_variant_id',v0));quote:=public.commerce_quote(items);
 result:=public.commerce_create_order(gen_random_uuid(),repeat('d',64),customer,items,quote->>'quote_hash',null,gen_random_uuid()::text,gen_random_uuid()::text);order_id:=(result->>'id')::uuid;
 assert (select stock from public.product_variants where id=v0)=1,'Same power uses two individual lenses';
 failure:=false;begin perform public.commerce_quote(items);exception when others then failure:=sqlerrm like '%OUT_OF_STOCK%';end;assert failure,'Insufficient same-power stock rejected';
 failure:=false;begin perform public.commerce_inventory_update(actor,fixture,'product',0,0,'[]');exception when others then failure:=sqlerrm like '%OPEN_ORDER_INVENTORY%';end;assert failure,'Cannot change inventory model under a pending reservation';
 perform public.commerce_transition_order(order_id,actor,'cancelled','{}');
 assert (select stock from public.product_variants where id=v0)=3,'Cancel restores SKU units';
 items:=jsonb_build_array(jsonb_build_object('product_id',fixture,'quantity',1,'left_variant_id',v0,'right_variant_id',v1));quote:=public.commerce_quote(items);
 result:=public.commerce_create_order(gen_random_uuid(),repeat('e',64),customer,items,quote->>'quote_hash',null,gen_random_uuid()::text,gen_random_uuid()::text);order_id:=(result->>'id')::uuid;
 assert (select stock from public.product_variants where id=v0)=2 and (select stock from public.product_variants where id=v1)=1,'Mixed eyes use one lens per SKU';
 perform public.commerce_transition_order(order_id,actor,'confirmed','{"shipping_fee":30000,"customer_confirmed":true}');
 assert (select total from public.orders where id=order_id)=250000,'Server computes COD total';
 perform public.commerce_transition_order(order_id,actor,'shipped','{"carrier":"Test carrier","tracking_code":"TEST-ONLY"}');
 perform public.commerce_transition_order(order_id,actor,'delivered','{}');
 perform public.commerce_transition_order(order_id,actor,'returned','{}');
 assert (select stock from public.product_variants where id=v0)=2,'Returned lenses are not silently resold';
 failure:=false;begin perform public.commerce_inventory_update(actor,fixture,'variant',0,0,jsonb_build_array(jsonb_build_object('power',0,'stock',9,'expected_stock',3)));exception when others then failure:=sqlerrm like '%STOCK_CHANGED%';end;assert failure,'Stale stock edits cannot overwrite reservations';
 perform public.commerce_inventory_update(actor,fixture,'variant',0,0,jsonb_build_array(jsonb_build_object('power',-2.25,'stock',4,'expected_stock',null)));
 assert (select stock from public.product_variants where product_id=fixture and power=-2.25)=4,'Verified SKU entry creates the intended power';
 assert not has_function_privilege('anon','public.commerce_create_order(uuid,text,jsonb,jsonb,text,uuid,text,text)','execute'),'Anonymous role cannot invoke privileged order RPC';
 assert not has_function_privilege('authenticated','public.commerce_transition_order(uuid,uuid,text,jsonb)','execute'),'Authenticated role cannot invoke privileged status RPC';
 assert not has_table_privilege('anon','public.orders','select'),'No public customer data table read';
 assert not has_table_privilege('authenticated','public.orders','update'),'Clients cannot edit order totals or status directly';
 assert not has_table_privilege('anon','public.product_reviews','insert'),'Only verified delivered orders can submit via server';
end $$;
set local role authenticated;
do $$begin assert (select count(id) from public.orders)=0,'An unrelated authenticated caller cannot read guest orders';end $$;
reset role;
rollback;
select 'Commerce database assertions passed; test orders and stock changes rolled back.' as result;
